
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_hjs_b97x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_hjs_b97x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.165764544394628e+00, -4.082903344218662e+00, -3.966857826370904e+00, -3.806241540023438e+00, -3.587678148287024e+00, -3.297451989939744e+00, -2.925441989295380e+00, -2.472428466311407e+00, -1.960765370759971e+00, -1.442101382541874e+00, -9.643301344208655e-01, -6.309474580076924e-01, -5.350140451773935e-01, -4.259739849812512e-01, -2.901625480583543e-01, -1.700557697217339e-01, -8.756246099589153e-02, -1.868653356029811e-02, -6.106232343852426e-05, -3.961282190978518e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


